/*
 * Godot C-ABI adapter for the GraalVM-compiled Minecraft input surface.
 * The Java layer does not know about Godot. This adapter owns the GDExtension
 * ABI and forwards plain integer touch data to the Java Native Image library.
 */
#ifndef _GNU_SOURCE
#define _GNU_SOURCE
#endif
#include <dlfcn.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "gdextension_interface.h"
#include "minecraft_java.h" /* generated by build.sh from native-image output */
#include "minecraft_render_abi.h"
#include "minecraft_render_native_state.h"

#if defined(_WIN32)
#define GDEXTENSION_EXPORT __declspec(dllexport)
#else
#define GDEXTENSION_EXPORT __attribute__((visibility("default")))
#endif

#define CLASS_NAME "MinecraftTouch"
#define PARENT_CLASS_NAME "RefCounted"

/* gdextension_interface.h returns a generic function pointer. The Godot API
 * explicitly permits an intermediate void-pointer cast for typed interfaces. */
#define LOAD_GODOT_INTERFACE(type, name) ((type)(void *)get_proc_address(name))

typedef struct {
    int placeholder;
} MinecraftTouchInstance;

static GDExtensionInterfaceGetProcAddress godot_get_proc_address;
static GDExtensionClassLibraryPtr godot_library;
static GDExtensionInterfaceStringNameNewWithUtf8Chars string_name_new;
static GDExtensionInterfaceClassdbConstructObject classdb_construct_object;
static GDExtensionInterfaceObjectSetInstance object_set_instance;
static GDExtensionInterfaceClassdbRegisterExtensionClass classdb_register_extension_class;
static GDExtensionInterfaceClassdbRegisterExtensionClassMethod classdb_register_extension_class_method;
static GDExtensionInterfaceGetVariantToTypeConstructor variant_to_int;
static GDExtensionInterfaceGetVariantFromTypeConstructor variant_from_int;
static GDExtensionInterfaceVariantNewNil variant_new_nil;
static GDExtensionInterfaceVariantConstruct variant_construct;
static GDExtensionInterfaceVariantCall variant_call;
static GDExtensionInterfaceVariantDestroy variant_destroy;
static GDExtensionInterfaceGetVariantGetInternalPtrFunc variant_get_internal_ptr;
static GDExtensionInterfacePackedByteArrayOperatorIndex packed_byte_array_index;

/* Godot's stable GDExtension Variant ABI reserves 24 bytes, aligned to 64-bit.
 * This is only used for temporary Variant arguments/returns constructed through
 * Godot's own ABI functions; no Godot C++ layout is assumed. */
typedef union MinecraftGodotVariant {
    uint8_t bytes[24];
    uint64_t alignment;
} MinecraftGodotVariant;

static graal_isolate_t *java_isolate;
static graal_isolatethread_t *java_main_thread;
static MinecraftRenderNativeState *render_native_state;

static GDExtensionStringNamePtr make_string_name(const char *text) {
    /* Official Godot 4.7 StringName is one pointer. Every C ABI function takes
     * a pointer to that object; returning the interned data pointer stored
     * inside it would make ClassDB/Variant calls read the wrong memory. */
    void *storage = calloc(1, sizeof(void *));
    if (storage == NULL) {
        return NULL;
    }
    string_name_new(storage, text);
    return storage;
}

/* Godot interns StringNames created through the C ABI. They are kept for the
 * process lifetime so all names used by this small extension are created once
 * per registration/lifetime and intentionally not freed here. */
static void free_string_name(GDExtensionStringNamePtr name) {
    (void)name;
}

static graal_isolatethread_t *java_thread(void) {
    if (java_isolate == NULL) {
        return NULL;
    }
    graal_isolatethread_t *thread = graal_get_current_thread(java_isolate);
    if (thread == NULL && graal_attach_thread(java_isolate, &thread) != 0) {
        return NULL;
    }
    return thread;
}

GDExtensionBool godot_gdextension_init(
        GDExtensionInterfaceGetProcAddress get_proc_address,
        GDExtensionClassLibraryPtr library,
        GDExtensionInitialization *initialization);

/* Point LWJGL at the natives directory beside this extension before the
 * isolate starts, so the extracted client loads the SDL viewport stub. */
static void export_native_dir(void) {
    Dl_info info;
    char path[4096];
    char natives[4096];
    const char *slash;
    size_t length;
    if (getenv("MINECRAFT_GODOT_NATIVE_DIR") != NULL) {
        return;
    }
    if (dladdr((void *)godot_gdextension_init, &info) == 0 || info.dli_fname == NULL) {
        return;
    }
    length = strlen(info.dli_fname);
    if (length == 0 || length >= sizeof(path)) {
        return;
    }
    memcpy(path, info.dli_fname, length + 1);
    slash = strrchr(path, '/');
    if (slash == NULL || slash == path) {
        return;
    }
    snprintf(natives, sizeof(natives), "%.*s/natives", (int)(slash - path), path);
    if (access(natives, R_OK) == 0) {
        setenv("MINECRAFT_GODOT_NATIVE_DIR", natives, 0);
        return;
    }
    path[slash - path] = '\0';
    setenv("MINECRAFT_GODOT_NATIVE_DIR", path, 0);
}

static int java_start(void) {
    graal_create_isolate_params_t params;
    char arg0[] = "minecraft";
    char *isolate_argv[] = {arg0, NULL};
    int status;
    if (java_isolate != NULL) {
        return 1;
    }
    export_native_dir();
    memset(&params, 0, sizeof(params));
    params.version = __graal_create_isolate_params_version;
    /* The extracted client image is large. The default reservation can fail
     * before any Java code runs. */
    params.reserved_address_space_size = (unsigned long)16 * 1024 * 1024 * 1024;
    params.argc = 1;
    params.argv = isolate_argv;
    params.ignore_unrecognized_args = 1;
    status = graal_create_isolate(&params, &java_isolate, &java_main_thread);
    if (status != 0) {
        java_isolate = NULL;
        java_main_thread = NULL;
        return 0;
    }
    minecraft_bootstrap(java_main_thread);
    return 1;
}

static void set_call_ok(GDExtensionCallError *error) {
    if (error != NULL) {
        error->error = GDEXTENSION_CALL_OK;
        error->argument = 0;
        error->expected = 0;
    }
}

static void set_argument_error(GDExtensionCallError *error, int argument, int expected) {
    if (error != NULL) {
        error->error = GDEXTENSION_CALL_ERROR_INVALID_ARGUMENT;
        error->argument = argument;
        error->expected = expected;
    }
}

static int64_t variant_int(GDExtensionConstVariantPtr value) {
    int64_t result = 0;
    GDExtensionTypeFromVariantConstructorFunc converter =
            variant_to_int(GDEXTENSION_VARIANT_TYPE_INT);
    converter(&result, (GDExtensionVariantPtr)value);
    return result;
}

static void return_int(GDExtensionVariantPtr result, int64_t value) {
    GDExtensionVariantFromTypeConstructorFunc constructor =
            variant_from_int(GDEXTENSION_VARIANT_TYPE_INT);
    constructor(result, &value);
}

static void return_nil(GDExtensionVariantPtr result) {
    variant_new_nil(result);
}

/*
 * Copies one bounded native range into a real PackedByteArray Variant. The
 * extension deliberately builds this through the public 4.7 ABI rather than
 * treating PackedByteArray as a C struct: Godot allocates/owns all Variant and
 * packed-array memory, and the caller receives an ordinary GDScript value.
 */
static bool return_packed_bytes(GDExtensionVariantPtr result, const uint8_t *bytes, size_t size) {
    static const uint8_t empty_byte = 0;
    if (bytes == NULL && size == 0) {
        bytes = &empty_byte;
    }
    if (bytes == NULL || size > MINECRAFT_RENDER_BRIDGE_MAX_CHUNK_BYTES ||
            size > INT64_MAX || variant_construct == NULL || variant_call == NULL ||
            variant_destroy == NULL || variant_get_internal_ptr == NULL ||
            packed_byte_array_index == NULL) {
        return false;
    }

    GDExtensionCallError call_error = {0};
    variant_construct(GDEXTENSION_VARIANT_TYPE_PACKED_BYTE_ARRAY, result, NULL, 0, &call_error);
    if (call_error.error != GDEXTENSION_CALL_OK) {
        return false;
    }
    if (size != 0) {
        MinecraftGodotVariant length_argument = {0};
        MinecraftGodotVariant resize_result = {0};
        int64_t length = (int64_t)size;
        GDExtensionVariantFromTypeConstructorFunc int_constructor =
                variant_from_int(GDEXTENSION_VARIANT_TYPE_INT);
        int_constructor(&length_argument, &length);
        static GDExtensionStringNamePtr resize_name;
        if (resize_name == NULL) {
            resize_name = make_string_name("resize");
        }
        if (resize_name == NULL) {
            variant_destroy(result);
            variant_destroy(&length_argument);
            return false;
        }
        const GDExtensionConstVariantPtr arguments[] = { &length_argument };
        variant_call(result, resize_name, arguments, 1, &resize_result, &call_error);
        int64_t resize_status = -1;
        if (call_error.error == GDEXTENSION_CALL_OK) {
            GDExtensionTypeFromVariantConstructorFunc int_reader =
                    variant_to_int(GDEXTENSION_VARIANT_TYPE_INT);
            int_reader(&resize_status, &resize_result);
        }
        variant_destroy(&length_argument);
        variant_destroy(&resize_result);
        if (call_error.error != GDEXTENSION_CALL_OK || resize_status != 0) {
            variant_destroy(result);
            return false;
        }
        GDExtensionVariantGetInternalPtrFunc get_packed_bytes =
                variant_get_internal_ptr(GDEXTENSION_VARIANT_TYPE_PACKED_BYTE_ARRAY);
        GDExtensionTypePtr packed_bytes = get_packed_bytes(result);
        uint8_t *destination = packed_bytes == NULL ? NULL : packed_byte_array_index(packed_bytes, 0);
        if (destination == NULL) {
            variant_destroy(result);
            return false;
        }
        memcpy(destination, bytes, size);
    }
    return true;
}

static GDExtensionObjectPtr minecraft_touch_create(void *class_userdata) {
    (void)class_userdata;
    GDExtensionStringNamePtr class_name = make_string_name(CLASS_NAME);
    GDExtensionObjectPtr object = classdb_construct_object(class_name);
    MinecraftTouchInstance *instance = calloc(1, sizeof(*instance));
    if (object != NULL && instance != NULL) {
        object_set_instance(object, class_name, instance);
    } else {
        free(instance);
    }
    free_string_name(class_name);
    return object;
}

static void minecraft_touch_free(void *class_userdata, GDExtensionClassInstancePtr instance) {
    (void)class_userdata;
    free(instance);
}

static void method_touch_down(void *userdata, GDExtensionClassInstancePtr instance,
        const GDExtensionConstVariantPtr *args, GDExtensionInt argument_count,
        GDExtensionVariantPtr result, GDExtensionCallError *error) {
    (void)userdata;
    (void)instance;
    if (argument_count != 5) {
        set_argument_error(error, (int)argument_count, 5);
        return_nil(result);
        return;
    }
    graal_isolatethread_t *thread = java_thread();
    if (thread != NULL) {
        minecraft_touch_down(thread, (int)variant_int(args[0]), (int)variant_int(args[1]),
                (int)variant_int(args[2]), (int)variant_int(args[3]), (int)variant_int(args[4]));
    }
    set_call_ok(error);
    return_nil(result);
}

