static void register_method(const char *name, uint32_t argument_count,
        GDExtensionClassMethodCall call, GDExtensionClassMethodPtrCall ptrcall,
        GDExtensionBool has_return_value) {
    GDExtensionStringNamePtr method_name = make_string_name(name);
    GDExtensionPropertyInfo return_info = {0};
    return_info.type = GDEXTENSION_VARIANT_TYPE_INT;

    GDExtensionPropertyInfo arguments[5] = {0};
    GDExtensionClassMethodArgumentMetadata metadata[5] = {0};
    for (uint32_t i = 0; i < argument_count; i++) {
        arguments[i].type = GDEXTENSION_VARIANT_TYPE_INT;
        metadata[i] = GDEXTENSION_METHOD_ARGUMENT_METADATA_INT_IS_INT64;
    }

    GDExtensionClassMethodInfo method = {0};
    method.name = method_name;
    method.call_func = call;
    method.ptrcall_func = ptrcall;
    method.method_flags = GDEXTENSION_METHOD_FLAGS_DEFAULT;
    method.has_return_value = has_return_value;
    method.return_value_info = has_return_value ? &return_info : NULL;
    method.return_value_metadata = GDEXTENSION_METHOD_ARGUMENT_METADATA_INT_IS_INT64;
    method.argument_count = argument_count;
    method.arguments_info = argument_count ? arguments : NULL;
    method.arguments_metadata = argument_count ? metadata : NULL;

    GDExtensionStringNamePtr class_name = make_string_name(CLASS_NAME);
    classdb_register_extension_class_method(godot_library, class_name, &method);
    free_string_name(class_name);
    free_string_name(method_name);
}

/* PackedByteArray returns intentionally use the generic Variant callback only.
 * The data bridge is always invoked through Object.call() from GDScript, which
 * keeps Godot responsible for constructing the opaque packed-array return. */
static void register_packed_byte_array_method(const char *name, uint32_t argument_count,
        GDExtensionClassMethodCall call) {
    GDExtensionStringNamePtr method_name = make_string_name(name);
    GDExtensionPropertyInfo return_info = {0};
    return_info.type = GDEXTENSION_VARIANT_TYPE_PACKED_BYTE_ARRAY;

    GDExtensionPropertyInfo arguments[5] = {0};
    GDExtensionClassMethodArgumentMetadata metadata[5] = {0};
    for (uint32_t i = 0; i < argument_count; i++) {
        arguments[i].type = GDEXTENSION_VARIANT_TYPE_INT;
        metadata[i] = GDEXTENSION_METHOD_ARGUMENT_METADATA_INT_IS_INT64;
    }

    GDExtensionClassMethodInfo method = {0};
    method.name = method_name;
    method.call_func = call;
    method.ptrcall_func = NULL;
    method.method_flags = GDEXTENSION_METHOD_FLAGS_DEFAULT;
    method.has_return_value = 1;
    method.return_value_info = &return_info;
    method.argument_count = argument_count;
    method.arguments_info = argument_count ? arguments : NULL;
    method.arguments_metadata = argument_count ? metadata : NULL;

    GDExtensionStringNamePtr class_name = make_string_name(CLASS_NAME);
    classdb_register_extension_class_method(godot_library, class_name, &method);
    free_string_name(class_name);
    free_string_name(method_name);
}

static void initialize_minecraft(void *userdata, GDExtensionInitializationLevel level) {
    (void)userdata;
    if (level != GDEXTENSION_INITIALIZATION_SCENE) {
        return;
    }

    if (!java_start()) {
        return;
    }
    render_native_state = minecraft_render_native_state_create();
    if (render_native_state == NULL) {
        return;
    }

    GDExtensionStringNamePtr class_name = make_string_name(CLASS_NAME);
    GDExtensionStringNamePtr parent_name = make_string_name(PARENT_CLASS_NAME);
    GDExtensionClassCreationInfo class_info = {0};
    class_info.is_virtual = 0;
    class_info.is_abstract = 0;
    class_info.create_instance_func = minecraft_touch_create;
    class_info.free_instance_func = minecraft_touch_free;
    classdb_register_extension_class(godot_library, class_name, parent_name, &class_info);
    free_string_name(parent_name);
    free_string_name(class_name);

    register_method("touch_down", 5, method_touch_down, ptrcall_touch_down, 0);
    register_method("touch_move", 5, method_touch_move, ptrcall_touch_move, 0);
    register_method("touch_up", 1, method_touch_up, ptrcall_touch_up, 0);
    register_method("reset", 0, method_reset, ptrcall_reset, 0);
    register_method("add_camera_drag", 2, method_add_camera_drag, ptrcall_add_camera_drag, 0);
    register_method("set_virtual_joystick_mask", 1, method_set_virtual_joystick_mask,
            ptrcall_set_virtual_joystick_mask, 0);
    register_method("submit_render_protocol_smoke_frame", 0,
            method_submit_render_protocol_smoke_frame,
            ptrcall_submit_render_protocol_smoke_frame, 1);
    register_method("execute_render_mailbox", 0, method_execute_render_mailbox,
            ptrcall_execute_render_mailbox, 1);
    register_method("get_render_buffer_count", 0, method_get_render_buffer_count,
            ptrcall_get_render_buffer_count, 1);
    register_method("get_render_buffer_attribute", 2, method_get_render_buffer_attribute,
            ptrcall_get_render_buffer_attribute, 1);
    register_method("get_render_texture_count", 0, method_get_render_texture_count,
            ptrcall_get_render_texture_count, 1);
    register_method("get_render_texture_attribute", 2, method_get_render_texture_attribute,
            ptrcall_get_render_texture_attribute, 1);
    register_method("get_render_pass_attribute", 1, method_get_render_pass_attribute,
            ptrcall_get_render_pass_attribute, 1);
    register_method("get_render_frame_pass_count", 0, method_get_render_frame_pass_count,
            ptrcall_get_render_frame_pass_count, 1);
    register_method("get_render_frame_pass_attribute", 2, method_get_render_frame_pass_attribute,
            ptrcall_get_render_frame_pass_attribute, 1);
    register_method("get_render_draw_count", 0, method_get_render_draw_count,
            ptrcall_get_render_draw_count, 1);
    register_method("get_render_draw_attribute", 2, method_get_render_draw_attribute,
            ptrcall_get_render_draw_attribute, 1);
    register_method("get_render_pipeline_attribute", 2, method_get_render_pipeline_attribute,
            ptrcall_get_render_pipeline_attribute, 1);
    register_method("get_render_pipeline_vertex_attribute", 3,
            method_get_render_pipeline_vertex_attribute,
            ptrcall_get_render_pipeline_vertex_attribute, 1);
    register_method("get_render_texture_mip_layer_size", 3,
            method_get_render_texture_mip_layer_size, NULL, 1);
    register_packed_byte_array_method("get_render_buffer_bytes", 3,
            method_get_render_buffer_bytes);
    register_packed_byte_array_method("get_render_texture_mip_layer_bytes", 5,
            method_get_render_texture_mip_layer_bytes);
    register_method("get_touch_mask", 0, method_get_touch_mask, ptrcall_get_touch_mask, 1);
    register_method("get_active_touch_count", 0, method_get_active_touch_count,
            ptrcall_get_active_touch_count, 1);
}

static void deinitialize_minecraft(void *userdata, GDExtensionInitializationLevel level) {
    (void)userdata;
    if (level != GDEXTENSION_INITIALIZATION_SCENE) {
        return;
    }
    if (java_isolate != NULL) {
        graal_isolatethread_t *thread = java_thread();
        if (thread != NULL) {
            minecraft_client_stop(thread);
            minecraft_touch_reset(thread);
            graal_tear_down_isolate(thread);
        }
        java_isolate = NULL;
        java_main_thread = NULL;
    }
    minecraft_render_native_state_destroy(render_native_state);
    render_native_state = NULL;
    minecraft_render_clear_latest_frame();
}

